@@ -0,0 +1,742 @@
+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
+<title>RD Global Connect — Destination Intelligence & AI Infrastructure</title>
+<meta name="description" content="RD Global Connect Co., Ltd. — the operational engine behind Experience Pattaya City and BESK Creative. DMC, MICE, government liaison and frontier AI digital infrastructure.">
+<meta name="theme-color" content="#0a0a0c">
+<link rel="preconnect" href="https://fonts.googleapis.com">
+<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
+<link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
+<style>
+:root{
+  --bg:#0a0a0c; --bg2:#0f0f13; --line:#1f1f23; --txt:#f4f6f8; --mut:#9aa0aa;
+  --cy:#00f2fe; --bl:#4facfe; --mg:#ff3d9a; --glass:rgba(255,255,255,.04);
+  --r:18px; --ease:cubic-bezier(.2,.7,.2,1);
+}
+*{box-sizing:border-box;margin:0;padding:0}
+html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
+body{background:var(--bg);color:var(--txt);font-family:'Outfit',system-ui,sans-serif;line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
+a{color:inherit;text-decoration:none}
+.mono{font-family:'JetBrains Mono',ui-monospace,monospace}
+.wrap{width:min(1240px,100% - 40px);margin-inline:auto}
+section{position:relative;padding:130px 0}
+h1,h2,h3{line-height:1.08;letter-spacing:-.025em;font-weight:700}
+h2{font-size:clamp(2rem,4.4vw,3.4rem)}
+.grad{background:linear-gradient(100deg,var(--cy),var(--bl) 55%,#b388ff);-webkit-background-clip:text;background-clip:text;color:transparent}
+.eyebrow{display:inline-flex;gap:.6rem;align-items:center;font:500 .74rem/1 'JetBrains Mono',monospace;letter-spacing:.14em;text-transform:uppercase;color:var(--cy)}
+.eyebrow::before{content:"";width:28px;height:1px;background:var(--cy);box-shadow:0 0 10px var(--cy)}
+.lead{color:var(--mut);font-size:1.12rem;max-width:62ch}
+.sec-head{margin-bottom:60px;display:grid;gap:18px}
+
+/* cursor glow */
+#glow{position:fixed;inset:0;pointer-events:none;z-index:1;background:radial-gradient(520px circle at var(--mx,50%) var(--my,30%),rgba(0,242,254,.07),transparent 60%)}
+#progress{position:fixed;top:0;left:0;height:2px;width:0;background:linear-gradient(90deg,var(--cy),var(--bl),var(--mg));z-index:100;box-shadow:0 0 12px var(--cy)}
+
+/* nav */
+header{position:fixed;inset:0 0 auto 0;z-index:50;transition:.4s var(--ease)}
+header.s{background:rgba(10,10,12,.72);backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);border-bottom:1px solid var(--line)}
+.nav{display:flex;align-items:center;justify-content:space-between;height:78px}
+.brand{display:flex;align-items:center;gap:12px;font-weight:700;letter-spacing:.18em;font-size:.95rem}
+.brand svg{width:34px;height:34px}
+.links{display:flex;gap:30px;align-items:center}
+.links a.l{font-size:.92rem;color:var(--mut);position:relative;transition:.3s}
+.links a.l:hover{color:#fff}
+.links a.l::after{content:"";position:absolute;left:0;bottom:-6px;height:1px;width:0;background:var(--cy);transition:.35s var(--ease);box-shadow:0 0 8px var(--cy)}
+.links a.l:hover::after{width:100%}
+.btn{display:inline-flex;align-items:center;gap:10px;padding:14px 26px;border-radius:999px;font-weight:600;font-size:.95rem;border:1px solid transparent;cursor:pointer;transition:.35s var(--ease);position:relative;overflow:hidden;font-family:inherit}
+.btn.p{background:linear-gradient(100deg,var(--cy),var(--bl));color:#031016;box-shadow:0 0 34px rgba(0,242,254,.28)}
+.btn.p:hover{transform:translateY(-2px);box-shadow:0 0 52px rgba(0,242,254,.5)}
+.btn.g{background:var(--glass);border-color:rgba(255,255,255,.16);color:#fff;backdrop-filter:blur(10px)}
+.btn.g:hover{border-color:var(--cy);box-shadow:0 0 28px rgba(0,242,254,.2);transform:translateY(-2px)}
+.btn.sm{padding:10px 20px;font-size:.86rem}
+.burger{display:none;background:none;border:1px solid var(--line);color:#fff;width:44px;height:44px;border-radius:12px;cursor:pointer}
+.burger span{display:block;width:18px;height:1.5px;background:#fff;margin:5px auto;transition:.3s}
+
+/* hero */
+.hero{min-height:100svh;padding:0;display:flex;align-items:center;overflow:hidden;isolation:isolate}
+.hero canvas.morph{position:absolute;inset:0;width:100%;height:100%;z-index:-3}
+#net{position:absolute;inset:0;width:100%;height:100%;z-index:-1}
+.hero::before{content:"";position:absolute;inset:0;z-index:-2;background:
+  linear-gradient(180deg,rgba(10,10,12,.7),rgba(10,10,12,.15) 38%,rgba(10,10,12,.75) 82%,var(--bg)),
+  radial-gradient(ellipse at 22% 55%,rgba(10,10,12,.82),transparent 62%)}
+.hero-in{padding:150px 0 190px;max-width:880px}
+.badge{display:inline-flex;align-items:center;gap:10px;padding:9px 16px;border-radius:999px;background:var(--glass);border:1px solid rgba(255,255,255,.12);backdrop-filter:blur(12px);font:500 .72rem/1 'JetBrains Mono',monospace;letter-spacing:.1em;text-transform:uppercase;color:#cfe;margin-bottom:28px}
+.dot{width:7px;height:7px;border-radius:50%;background:var(--cy);box-shadow:0 0 12px var(--cy);animation:pulse 2s infinite}
+@keyframes pulse{50%{opacity:.3;transform:scale(.7)}}
+.hero h1{font-size:clamp(2.5rem,6.2vw,5.4rem);margin-bottom:26px}
+.hero .lead{font-size:clamp(1.02rem,1.5vw,1.25rem);color:#c3c8d0;margin-bottom:38px}
+.cta{display:flex;gap:14px;flex-wrap:wrap}
+.scene-tag{position:absolute;right:20px;bottom:150px;display:flex;align-items:center;gap:12px;font:500 .72rem/1.3 'JetBrains Mono',monospace;color:#cfd6df;text-align:right;letter-spacing:.06em}
+.scene-tag b{display:block;color:var(--cy);font-weight:500}
+.scene-bars{display:flex;gap:6px}
+.scene-bars i{width:30px;height:3px;background:rgba(255,255,255,.2);border-radius:3px;overflow:hidden;position:relative;cursor:pointer}
+.scene-bars i.on::after{content:"";position:absolute;inset:0;background:var(--cy);transform-origin:left;animation:fill var(--dur,6s) linear forwards}
+@keyframes fill{from{transform:scaleX(0)}to{transform:scaleX(1)}}
+.metrics{position:absolute;left:0;right:0;bottom:0;border-top:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,transparent,rgba(10,10,12,.85));backdrop-filter:blur(8px)}
+.metrics .wrap{display:grid;grid-template-columns:repeat(3,1fr)}
+.m{padding:26px 28px 26px 0;border-right:1px solid rgba(255,255,255,.08)}
+.m+.m{padding-left:28px}.m:last-child{border:0}
+.m small{display:block;font:500 .68rem/1 'JetBrains Mono',monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--cy);margin-bottom:10px}
+.m p{font-size:.95rem;color:#d3d8df;line-height:1.45}
+
+/* ecosystem */
+.eco{background:radial-gradient(ellipse at 50% 0,rgba(79,172,254,.07),transparent 60%)}
+#constel{width:100%;height:auto;display:block;margin-bottom:34px;border:1px solid var(--line);border-radius:28px;background:linear-gradient(160deg,#0d0d11,#09090b);overflow:visible}
+#constel .edge{stroke:rgba(0,242,254,.35);stroke-width:1.2;fill:none;stroke-dasharray:4 7;animation:dash 22s linear infinite}
+#constel .edge.dim{stroke:rgba(255,255,255,.13)}
+@keyframes dash{to{stroke-dashoffset:-400}}
+#constel text{fill:#e9edf2;font-family:'Outfit',sans-serif}
+#constel .sub{font:500 11px 'JetBrains Mono',monospace;fill:#7f8794;letter-spacing:.08em}
+#constel g.node{cursor:pointer}
+#constel g.node circle.ring{transition:.4s var(--ease);transform-box:fill-box;transform-origin:center}
+#constel g.node:hover circle.ring,#constel g.node.act circle.ring{transform:scale(1.25);stroke-width:2}
+.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
+.card{position:relative;padding:34px;border-radius:var(--r);background:var(--glass);border:1px solid rgba(255,255,255,.09);backdrop-filter:blur(14px);transition:.5s var(--ease);overflow:hidden}
+.card::before{content:"";position:absolute;inset:0;background:radial-gradient(420px circle at var(--cx,50%) var(--cy2,0%),rgba(0,242,254,.12),transparent 55%);opacity:0;transition:.4s}
+.card:hover{transform:translateY(-6px);border-color:rgba(0,242,254,.4)}
+.card:hover::before{opacity:1}
+.card>*{position:relative}
+.card .role{font:500 .7rem/1 'JetBrains Mono',monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--cy);margin-bottom:16px;display:block}
+.card h3{font-size:1.45rem;margin-bottom:6px}
+.card .sub2{color:var(--mut);margin-bottom:18px;font-size:.95rem}
+.card p{color:#c1c6ce;font-size:.96rem}
+.card .ref{display:inline-block;margin-top:20px;font:500 .8rem 'JetBrains Mono',monospace;color:var(--bl);border-bottom:1px solid rgba(79,172,254,.4)}
+.ico{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(0,242,254,.18),rgba(79,172,254,.05));border:1px solid rgba(0,242,254,.3);margin-bottom:22px}
+.ico svg{width:22px;height:22px;stroke:var(--cy);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
+
+/* connect lab */
+.lab{background:#08080a;border-block:1px solid var(--line);overflow:hidden}
+.lab-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:34px;align-items:stretch}
+.stage{position:relative;border-radius:26px;overflow:hidden;border:1px solid rgba(0,242,254,.25);box-shadow:0 0 90px rgba(0,242,254,.08);aspect-ratio:16/10;min-height:280px;background:#000}
+.stage canvas{position:absolute;inset:0;width:100%;height:100%;cursor:crosshair}
+.stage .hud{position:absolute;left:18px;top:16px;right:18px;display:flex;justify-content:space-between;font:500 .7rem 'JetBrains Mono',monospace;letter-spacing:.1em;color:#d5fbff;text-transform:uppercase;pointer-events:none;text-shadow:0 0 8px #000}
+.stage .prompt{position:absolute;left:16px;right:16px;bottom:16px;padding:14px 18px;border-radius:14px;background:rgba(8,10,14,.66);backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.12);font:400 .82rem/1.5 'JetBrains Mono',monospace;color:#dff;min-height:56px;pointer-events:none}
+.prompt .caret{display:inline-block;width:7px;height:1em;background:var(--cy);vertical-align:-2px;animation:pulse 1s infinite}
+.panel{display:flex;flex-direction:column;gap:20px}
+.chips{display:grid;gap:10px}
+.chip{display:flex;align-items:center;gap:14px;text-align:left;padding:14px 18px;border-radius:14px;background:var(--glass);border:1px solid rgba(255,255,255,.09);color:#fff;font:inherit;cursor:pointer;transition:.35s var(--ease)}
+.chip:hover{border-color:rgba(0,242,254,.5)}
+.chip.on{background:linear-gradient(100deg,rgba(0,242,254,.14),rgba(79,172,254,.04));border-color:var(--cy);box-shadow:0 0 30px rgba(0,242,254,.14)}
+.chip i{font:500 .7rem 'JetBrains Mono',monospace;color:var(--cy);font-style:normal}
+.chip span{display:block;font-weight:600}.chip small{color:var(--mut);font-size:.82rem}
+.scrub{display:grid;gap:10px;font:500 .72rem 'JetBrains Mono',monospace;color:var(--mut);letter-spacing:.1em;text-transform:uppercase}
+input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:4px;border-radius:4px;background:linear-gradient(90deg,var(--cy),var(--bl));outline:none}
+input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:22px;height:22px;border-radius:50%;background:#fff;box-shadow:0 0 0 5px rgba(0,242,254,.3),0 0 22px var(--cy);cursor:grab}
+input[type=range]::-moz-range-thumb{width:22px;height:22px;border:0;border-radius:50%;background:#fff;box-shadow:0 0 0 5px rgba(0,242,254,.3);cursor:grab}
+.pipe{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font:500 .72rem 'JetBrains Mono',monospace;color:var(--mut)}
+.pipe b{padding:6px 11px;border-radius:8px;border:1px solid rgba(255,255,255,.12);color:#dfe6ee;font-weight:500}
+.pipe em{color:var(--cy);font-style:normal}
+
+/* pillars */
+.pillars{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}
+.pillar{padding:42px}
+.pillar .n{position:absolute;right:28px;top:14px;font:700 5.5rem/1 'Outfit';color:rgba(255,255,255,.035);letter-spacing:-.04em}
+.pillar h3{font-size:1.55rem;margin-bottom:20px;max-width:90%}
+.pillar ul{list-style:none;display:grid;gap:14px}
+.pillar li{padding-left:26px;position:relative;color:#c1c6ce;font-size:.97rem}
+.pillar li::before{content:"";position:absolute;left:0;top:.62em;width:12px;height:1px;background:var(--cy);box-shadow:0 0 8px var(--cy)}
+.pillar li b{color:#fff;font-weight:600}
+.agency{display:grid;gap:12px;margin:6px 0 4px}
+.agency div{padding:14px 16px;border-radius:12px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);font-size:.92rem;color:#c1c6ce}
+.agency strong{color:var(--cy);font:500 .85rem 'JetBrains Mono',monospace;margin-right:8px}
+
+/* tech */
+.tech{padding:70px 0;border-block:1px solid var(--line);background:#0b0b0e}
+.tech-rows{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-bottom:40px}
+.tech-rows h4{font:500 .72rem 'JetBrains Mono',monospace;letter-spacing:.14em;text-transform:uppercase;color:var(--cy);margin-bottom:12px}
+.tech-rows p{color:#d3d8df}
+.marquee{overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent);-webkit-mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent)}
+.track{display:flex;gap:56px;width:max-content;animation:mq 38s linear infinite;font:700 clamp(1.6rem,3.4vw,2.6rem)/1 'Outfit';color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.28);white-space:nowrap}
+.track span:nth-child(3n){-webkit-text-stroke:1px var(--cy);color:rgba(0,242,254,.06)}
+@keyframes mq{to{transform:translateX(-50%)}}
+
+/* contact */
+.contact{background:radial-gradient(ellipse at 80% 100%,rgba(0,242,254,.08),transparent 55%)}
+.c-grid{display:grid;grid-template-columns:1fr 1fr;gap:50px}
+.cats{display:grid;gap:10px;margin:28px 0}
+.cat{padding:16px 20px;border-radius:14px;background:var(--glass);border:1px solid rgba(255,255,255,.09);display:flex;justify-content:space-between;align-items:center;cursor:pointer;transition:.35s var(--ease);color:#fff;font:inherit;text-align:left;width:100%}
+.cat:hover,.cat.on{border-color:var(--cy);transform:translateX(6px);background:rgba(0,242,254,.06)}
+form{display:grid;gap:14px;padding:34px;border-radius:22px;background:var(--glass);border:1px solid rgba(255,255,255,.1);backdrop-filter:blur(16px)}
+label{font:500 .7rem 'JetBrains Mono',monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--mut);display:grid;gap:8px}
+input,textarea,select{background:rgba(0,0,0,.4);border:1px solid var(--line);color:#fff;padding:14px 16px;border-radius:12px;font:400 1rem 'Outfit',sans-serif;outline:none;transition:.3s;width:100%}
+input:focus,textarea:focus,select:focus{border-color:var(--cy);box-shadow:0 0 0 3px rgba(0,242,254,.14)}
+select option{background:#111}
+textarea{min-height:120px;resize:vertical}
+footer{border-top:1px solid var(--line);padding:50px 0 40px;color:var(--mut);font-size:.9rem}
+.f-row{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap}
+footer b{color:#fff;letter-spacing:.14em}
+
+.rv{opacity:0;transform:translateY(34px);transition:1s var(--ease)}
+.rv.in{opacity:1;transform:none}
+.d1{transition-delay:.12s}.d2{transition-delay:.24s}
+
+@media(max-width:980px){
+  section{padding:90px 0}
+  .links{position:fixed;inset:78px 0 auto 0;flex-direction:column;align-items:stretch;gap:0;background:rgba(10,10,12,.96);backdrop-filter:blur(20px);padding:10px 20px 26px;border-bottom:1px solid var(--line);transform:translateY(-130%);transition:.5s var(--ease)}
+  .links.open{transform:none}
+  .links a.l{padding:16px 0;border-bottom:1px solid var(--line);font-size:1.05rem}
+  .links .btn{margin-top:18px;justify-content:center}
+  .burger{display:block}
+  .grid3,.pillars,.lab-grid,.c-grid,.tech-rows{grid-template-columns:1fr}
+  .metrics{position:relative;margin-top:-120px}
+  .metrics .wrap{grid-template-columns:1fr}
+  .m,.m+.m{padding:18px 0;border-right:0;border-bottom:1px solid rgba(255,255,255,.08)}
+  .hero{align-items:flex-start;flex-direction:column;justify-content:space-between}
+  .hero-in{padding:130px 0 120px}
+  .scene-tag{display:none}
+  .pillar{padding:30px}
+}
+@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.rv{opacity:1;transform:none}}
+</style>
+</head>
+<body>
+<div id="progress"></div><div id="glow"></div>
+
+<header id="hd">
+  <div class="wrap nav">
+    <a href="#top" class="brand" aria-label="RD Global Connect">
+      <svg viewBox="0 0 40 40" fill="none"><defs><linearGradient id="lg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#00f2fe"/><stop offset="1" stop-color="#4facfe"/></linearGradient></defs>
+        <circle cx="8" cy="20" r="3.4" fill="url(#lg)"/><circle cx="31" cy="9" r="3.4" fill="url(#lg)"/><circle cx="31" cy="31" r="3.4" fill="url(#lg)"/><circle cx="20" cy="20" r="2" fill="#fff"/>
+        <path d="M8 20 20 20 31 9M20 20 31 31" stroke="url(#lg)" stroke-width="1.6"/></svg>
+      RD GLOBAL CONNECT
+    </a>
+    <nav class="links" id="links">
+      <a class="l" href="#ecosystem">Ecosystem</a>
+      <a class="l" href="#capabilities">Core Capabilities</a>
+      <a class="l" href="#lab">Digital &amp; AI</a>
+      <a class="l" href="#government">Government &amp; MICE</a>
+      <a class="l" href="#contact">Contact</a>
+      <a class="btn p sm" href="#contact">Partner With Us / Inquire</a>
+    </nav>
+    <button class="burger" id="burger" aria-label="Menu"><span></span><span></span></button>
+  </div>
+</header>
+
+<main id="top">
+<!-- HERO -->
+<section class="hero" aria-label="Introduction">
+  <canvas class="morph" id="heroMorph"></canvas>
+  <canvas id="net"></canvas>
+  <div class="wrap">
+    <div class="hero-in">
+      <div class="badge rv"><span class="dot"></span>Institutional Operations • Destination Intelligence • Digital Infrastructure</div>
+      <h1 class="rv d1">The Operational Engine Behind <span class="grad">Regional Destination Platforms</span> &amp; Next-Gen Digital Experiences.</h1>
+      <p class="lead rv d2">RD Global Connect bridges physical execution, government-grade destination management, and frontier AI digital infrastructure. We power high-impact platforms like Experience Pattaya City and execute elite production and tech initiatives for BESK Creative.</p>
+      <div class="cta rv d2">
+        <a class="btn p" href="#ecosystem">Explore Our Ecosystem <span>→</span></a>
+        <a class="btn g" href="#contact">Contact Corporate Desk</a>
+      </div>
+    </div>
+  </div>
+  <div class="scene-tag" id="heroTag">
+    <div><b id="tagName">—</b><span id="tagSub"></span></div>
+    <div class="scene-bars" id="heroBars"></div>
+  </div>
+  <div class="metrics">
+    <div class="wrap">
+      <div class="m"><small>DMC &amp; MICE Infrastructure</small><p>Tier-1 Venue &amp; Government Alignment</p></div>
+      <div class="m"><small>Digital Reach</small><p>Multi-Platform Tourism &amp; Nightlife Engines</p></div>
+      <div class="m"><small>Technology</small><p>3D WebGL, Multi-Agent AI Pipelines &amp; Secure Integrations</p></div>
+    </div>
+  </div>
+</section>
+
+<!-- ECOSYSTEM -->
+<section class="eco" id="ecosystem">
+  <div class="wrap">
+    <div class="sec-head">
+      <span class="eyebrow rv">Strategic Ecosystem</span>
+      <h2 class="rv d1">One core. <span class="grad">Every connection</span> runs through it.</h2>
+      <p class="lead rv d2">RD Global Connect anchors platforms, agencies and institutions in a single operating architecture. Hover a node to trace its links.</p>
+    </div>
+
+    <svg id="constel" viewBox="0 0 1100 520" role="img" aria-label="Ecosystem diagram: RD Global Connect at the centre linked to Experience Pattaya City, BESK Creative, NXGT, government bodies and technology partners">
+      <defs>
+        <radialGradient id="hubg"><stop offset="0" stop-color="#00f2fe" stop-opacity=".55"/><stop offset="1" stop-color="#00f2fe" stop-opacity="0"/></radialGradient>
+        <filter id="blur"><feGaussianBlur stdDeviation="2"/></filter>
+      </defs>
+      <circle cx="550" cy="260" r="150" fill="url(#hubg)"/>
+      <g id="edges"></g>
+      <g id="nodes"></g>
+    </svg>
+
+    <div class="grid3">
+      <article class="card rv">
+        <div class="ico"><svg viewBox="0 0 24 24"><path d="M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg></div>
+        <span class="role">Sole Operational &amp; Destination Management Entity</span>
+        <h3>Experience Pattaya City (EPC)</h3>
+        <div class="sub2">Destination Portal &amp; Smart Tourism</div>
+        <p>Digital platform management, official municipal collaborations, tourism ecosystem monetization, and international visitor onboarding.</p>
+        <a class="ref" href="https://experiencepattayacity.com" target="_blank" rel="noopener">experiencepattayacity.com ↗</a>
