  sats.forEach(function(o){var an=t*.35+o.off,d=S[4]*(1+Math.sin(t*.5+o.off)*.06);
    o.g.position.set(Math.cos(an)*d,Math.sin(an*.7+o.off)*d*.45,Math.sin(an)*d*.55);
    o.g.scale.setScalar(Math.max(.0001,S[3]*o.r*1.5));o.g.visible=S[3]>.02});
  renderer.render(scene,camera);
}
requestAnimationFrame(frame);
}

