const {chromium}=require('playwright');const fs=require('fs');(async()=>{const d=__dirname+'/';
const b=await chromium.launch({args:['--use-gl=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist','--no-sandbox']});
const three=fs.readFileSync(d+'three/package/build/three.min.js');
const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body>'+fs.readFileSync(d+'swiss2.html','utf8')+'</body></html>';
const p=await b.newPage({viewport:{width:1440,height:900}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.route('https://cdn.jsdelivr.net/**',r=>r.fulfill({body:three,contentType:'application/javascript'}));await p.route('https://fonts.*/**',r=>r.abort());
await p.setContent(html,{waitUntil:'domcontentloaded'});await p.waitForTimeout(7500);await p.screenshot({path:d+'x_hero.png'});
for(const [n,y] of [['b',1],['c',2],['d',3]]){await p.evaluate(y=>scrollTo({top:y*900,behavior:'instant'}),y);await p.waitForTimeout(2500);await p.screenshot({path:d+'x_'+n+'.png'})}
await p.evaluate(()=>document.querySelector('#what').scrollIntoView());await p.waitForTimeout(800);await p.screenshot({path:d+'x_what.png'});
console.log('nogl',await p.evaluate(()=>document.documentElement.classList.contains('nogl')),'ovX',await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),e.join('|')||'no errors');
await b.close()})();

