const fs = require('fs');
const d = __dirname + '/';
const topo = require(d + 'x_topojson-client-3.1.0/package/dist/topojson-client.js');
const w = JSON.parse(fs.readFileSync(d + 'x_world-atlas-2.0.2/package/countries-10m.json', 'utf8'));
const want = { 'Switzerland': 'CHE', 'Thailand': 'THA', 'United Arab Emirates': 'ARE' };
const out = {};
for (const g of w.objects.countries.geometries) {
  const name = g.properties && g.properties.name;
  if (want[name]) {
    const f = topo.feature(w, g);
    out[want[name]] = f.geometry;
  }
}
fs.writeFileSync(d + 'countries.json', JSON.stringify(out));
console.log(Object.keys(out), Object.values(out).map(g => g.type + ':' + (g.type === 'Polygon' ? g.coordinates.length : g.coordinates.length)));

