import re
d = '/tmp/claude-0/-home-user-mars-sandbox/eda22a4b-fb0b-53b5-8c75-12a0626db0dd/scratchpad/'
s = open(d + 'swiss3.html').read()

def rep(a, b, count=1):
    global s
    assert s.count(a) == count, (a[:70], s.count(a))
    s = s.replace(a, b)

# ---------- CSS ----------
rep('/* hero */', '''/* scroll stage: a pinned canvas plays the Blender frames while text steps fade in and out */
.stage{position:relative;height:800vh}
.pin{position:sticky;top:0;height:100vh;overflow:hidden;background:#ebebe9}
#seq{position:absolute;inset:0;width:100%;height:100%;display:block}
.pin::after{content:"";position:absolute;left:0;right:0;bottom:0;height:14vh;background:linear-gradient(to bottom,rgba(255,255,255,0),#fff);pointer-events:none}
.st{position:absolute;left:max(20px,calc((100vw - 1240px)/2));top:50%;width:min(560px,calc(100vw - 40px));transform:translateY(-50%);opacity:0;pointer-events:none;display:grid;gap:22px}
.st.on{pointer-events:auto}
.st h1{font-size:clamp(3rem,7.4vw,7.6rem);font-weight:500;letter-spacing:-.055em;line-height:.95;text-wrap:balance}
.st h2{font-size:clamp(2.4rem,5.4vw,5rem)}
.rail{position:absolute;left:max(20px,calc((100vw - 1240px)/2));bottom:34px;display:flex;gap:18px;font-size:.7rem;letter-spacing:.14em;color:#9a958d;list-style:none;margin:0;padding:0;z-index:2}
.rail li{transition:color .3s}.rail li.on{color:var(--ink)}
.bar{position:absolute;left:max(20px,calc((100vw - 1240px)/2));bottom:62px;height:6px;width:44px;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0.1));border-radius:1px;z-index:2}
/* hero */''')
rep('.hero{padding-top:72px}', '.hero{padding-top:72px}\n.nohero{display:none}')

# mobile
rep('  .hero-grid,.row,.contact,.lead-sec{grid-template-columns:1fr}',
    '  .st{top:auto;bottom:86px;transform:none;padding:22px;border-radius:22px;background:rgba(255,255,255,.86);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}\n  .st h1{font-size:clamp(2.6rem,12vw,3.6rem)}.st h2{font-size:clamp(2rem,9vw,2.8rem)}\n  .hero-grid,.row,.contact,.lead-sec{grid-template-columns:1fr}')

# ---------- HTML: replace the hero with the stage ----------
a = s.index('<section class="hero">')
b = s.index('</section>', a) + len('</section>')
stage = '''<section class="stage" id="stage" aria-label="Introduction">
    <div class="pin">
      <canvas id="seq" aria-hidden="true"></canvas>
      <div class="st" data-a="0" data-b="0.95">
        <p class="label"><span>RD Global Connect Co., Ltd.</span> · <span data-i18n="h_l">Chon Buri, Thailand</span></p>
        <h1 data-i18n="h_h">Where connections become power.</h1>
        <p class="lead" data-i18n="h_p">RD Global Connect links destinations, institutions, technology and people, and runs the operation on the ground. We take on the hard part so your plans actually happen.</p>
      </div>
      <div class="st" data-a="1.1" data-b="1.95">
        <p class="label"><b>01</b> · <span data-i18n="s1_l">Power</span></p>
        <h2 data-i18n="s1_h">We carry it out on the ground.</h2>
        <p class="lead" data-i18n="s1_p">Destination management, ground logistics, event production, and the venue and vendor contracts behind them. Plans are easy. Execution is what we do.</p>
      </div>
      <div class="st" data-a="2.55" data-b="3.45">
        <p class="label"><b>02</b> · <span data-i18n="z1_l">Switzerland</span></p>
        <h2 data-i18n="z1_h">Your market. Our standard.</h2>
        <p class="lead" data-i18n="z1_p">We plan and run operations to Swiss expectations: precise, reliable and accountable from the first step to the last.</p>
      </div>
      <div class="st" data-a="4.25" data-b="5.15">
        <p class="label"><b>03</b> · <span data-i18n="z2_l">Thailand</span></p>
        <h2 data-i18n="z2_h">Our ground.</h2>
        <p class="lead" data-i18n="z2_p">Based in Chon Buri and operating from Pattaya: destination management, logistics and events, carried out on site.</p>
      </div>
      <div class="st" data-a="5.95" data-b="7.1">
        <p class="label"><b>04</b> · <span data-i18n="z3_l">Dubai</span></p>
        <h2 data-i18n="z3_h">Connected further.</h2>
        <p class="lead" data-i18n="z3_p">Together with BESK Creative, our network reaches beyond Thailand, from creative production to technology.</p>
      </div>
      <i class="bar" id="bar"></i>
