player = r'''/* ---------- scroll sequence (Blender frames) ---------- */
var FR=144,frames=new Array(FR),loaded=0,ready=false;
var cv=$('#seq'),ctx=cv.getContext('2d'),stage=$('#stage'),bar=$('#bar'),steps=$$('.st'),rail=$$('.rail li');
var KP=[[0,0],[1,36],[1.9,46],[2.5,78],[3.5,90],[4.2,108],[5.2,118],[5.9,134],[7,143]];
function fOf(p){if(p<=0)return 0;for(var i=0;i<KP.length-1;i++){var a=KP[i],b=KP[i+1];if(p<=b[0])return a[1]+(b[1]-a[1])*((p-a[0])/(b[0]-a[0]))}return FR-1}
function sm(t){t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)}
var W=0,H=0,dpr=1,cur=-1,tgt=0,shown=0;
function size(){dpr=Math.min(devicePixelRatio||1,1.5);W=cv.clientWidth;H=cv.clientHeight;cv.width=W*dpr;cv.height=H*dpr;cur=-1}
function draw(f){
  var a=Math.floor(f),b=Math.min(a+1,FR-1),k=f-a,A=frames[a],B=frames[b];
  if(!A||!A.complete||!A.naturalWidth)return;
  var iw=A.naturalWidth,ih=A.naturalHeight,vw=cv.width,vh=cv.height,ar=vw/vh,ia=iw/ih,sw,sh,sx,sy;
  if(ar<ia){sh=ih;sw=ih*ar;sx=Math.max(0,Math.min(iw-sw,iw*0.6-sw/2));sy=0}else{sw=iw;sh=iw/ar;sx=0;sy=(ih-sh)/2}
  ctx.globalAlpha=1;ctx.drawImage(A,sx,sy,sw,sh,0,0,vw,vh);
  if(k>0.02&&B&&B.complete&&B.naturalWidth){ctx.globalAlpha=k;ctx.drawImage(B,sx,sy,sw,sh,0,0,vw,vh);ctx.globalAlpha=1}
}
function sync(){
  var r=stage.getBoundingClientRect(),vh=innerHeight,p=Math.max(0,Math.min(7,-r.top/vh));
  tgt=fOf(p);
  steps.forEach(function(el){var a=+el.dataset.a,b=+el.dataset.b,m=.22,o=Math.min(sm((p-a)/m),1-sm((p-b+m)/m));
    if(+el.dataset.a===0)o=1-sm((p-b+m)/m);if(+el.dataset.b>=7)o=sm((p-a)/m);
    el.style.opacity=o.toFixed(3);el.style.transform=innerWidth<=860?'translateY('+((1-o)*18).toFixed(1)+'px)':'translateY(calc(-50% + '+((1-o)*22).toFixed(1)+'px))';el.classList.toggle('on',o>.5)});
  var act=p<1?0:p<2.3?1:p<3.9?2:p<5.55?3:4;rail.forEach(function(li,i){li.classList.toggle('on',i<=act&&i===act)});
  bar.style.setProperty('--p',(0.1+0.9*(p/7)).toFixed(3));
}
function loop(){
  shown+=(tgt-shown)*0.14;if(Math.abs(tgt-shown)<0.01)shown=tgt;
  if(ready&&Math.abs(shown-cur)>0.001){draw(shown);cur=shown}
  requestAnimationFrame(loop)}
addEventListener('scroll',sync,{passive:true});addEventListener('resize',function(){size();sync()});size();sync();requestAnimationFrame(loop);

/* ---------- loader: counts real frame loading, logo wipes in, curtain lifts ---------- */
var started=false;
function reveal(){if(started)return;started=true;ready=true;size();cur=-1;sync();var L=$('#loader');L.classList.add('out');root.classList.remove('lock');root.classList.add('ready');document.body.classList.add('ready');setTimeout(function(){L.style.display='none'},1100)}
(function(){
  if(!root.classList.contains('js'))return;
  root.classList.add('lock');
  var n=$('#lnum'),barl=$('#lbar'),t0=performance.now(),shownP=0,minMs=reduce?200:2400,idx=0,doneAll=false;
  function onLoad(){loaded++;if(loaded>=FR)doneAll=true}
  function next(){if(idx>=FR)return;var i=idx++,im=new Image();im.onload=im.onerror=function(){onLoad();next()};im.src='frames/f'+('00'+i).slice(-3)+'.jpg';frames[i]=im}
  for(var c=0;c<6;c++)next();
  (function tick(now){
    var real=loaded/FR,time=Math.min(1,(now-t0)/minMs),target=Math.min(real,time);
    shownP+=(target-shownP)*0.2;var v=Math.round(shownP*100);n.textContent=v;barl.style.setProperty('--p',v+'%');
    if((doneAll&&time>=1&&shownP>.985)){n.textContent=100;barl.style.setProperty('--p','100%');setTimeout(reveal,240);return}
    requestAnimationFrame(tick)})(t0);
  setTimeout(function(){if(!started){reveal()}},30000);
})();
'''
